public static String testableHtml(
      PageData pageData,
      boolean includeSuiteSetup
      ) throws Exception {
          StringBuffer buffer = generatePageContent(pageData, includeSuiteSetup);
          pageData.setContent(buffer.toString());
          return pageData.getHTML();
      }

      private static StringBuffer generatePageContent(PageData pageData, boolean includeSuiteSetup) throws Exception {
          WikiPage wikiPage = pageData.getWikiPage();
          StringBuffer buffer = new StringBuffer();
          if(pageData.hasAttribute("Test")){
              appendSetup(buffer, wikiPage, includeSuiteSetup);
          }
          buffer.append(pageData.getContent());
          if(pageData.hasAttribute("Test")){
              appendTeardown(buffer, wikiPage, includeSuiteSetup);
          }
          return buffer;
      }

      private static void appendSetup(StringBuffer buffer, WikiPage wikiPage, boolean includeSuiteSetup) throws Exception {
          if (includeSuiteSetup) {
              appendInclude(buffer, PageCrawlerImpl.getInheritedPage(
                        SuiteResponder.SUITE_SETUP_NAME, wikiPage), "! include -setup .");
          }
          appendInclude(buffer, PageCrawlerImpl.getInheritedPage("SetUp", wikiPage), "! include -setup .");
      }

      private static void appendTeardown(StringBuffer buffer, WikiPage wikiPage, boolean includeSuiteSetup) throws Exception {
          appendInclude(buffer, PageCrawlerImpl.getInheritedPage("TearDown", wikiPage), "!include -teardown .");
          if (includeSuiteSetup) {
              appendInclude(buffer, PageCrawlerImpl.getInheritedPage(
                        SuiteResponder.SUITE_TEARDOWN_NAME, wikiPage), "!include -teardown .");
          }
      }

      private static void appendInclude(StringBuffer buffer, WikiPage page, String directive) throws Exception {
          if (page != null) {
              WikiPagePath path = page.getPageCrawler().getFullPath(page);
              buffer.append(directive).append(PathParser.render(path)).append("\n");
          }
      }
